sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float threshold;
uniform float intensity;
layout(color) uniform half4 color;
uniform float opacity;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half4 g = blurred.eval(coord);
    float3 soft = g.a > 0.0 ? float3(g.rgb) / float(g.a) : float3(0.0);
    float3 bright = max(soft - threshold, 0.0) / max(1.0 - threshold, 0.001);
    float3 glow = bright * float3(color.rgb) * intensity * clamp(opacity, 0.0, 1.0) * float(g.a);
    float a = max(float(c.a), clamp(max(glow.r, max(glow.g, glow.b)), 0.0, 1.0));
    return half4(half3(min(float3(c.rgb) + glow, float3(a))), half(a));
}
